import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"SOP: Replace Database Sheet Data from Generated TSVs","description":"","frontmatter":{},"headers":[],"relativePath":"sop-database-import.md","filePath":"sop-database-import.md"}'),r={name:"sop-database-import.md"};function d(i,e,n,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="sop-replace-database-sheet-data-from-generated-tsvs" tabindex="-1">SOP: Replace Database Sheet Data from Generated TSVs <a class="header-anchor" href="#sop-replace-database-sheet-data-from-generated-tsvs" aria-label="Permalink to &quot;SOP: Replace Database Sheet Data from Generated TSVs&quot;">​</a></h1><p>Use this procedure whenever you need to seed or replace the contents of a tenant&#39;s database Google Sheet — for example when setting up a demo environment, resetting test data, or bootstrapping a new tenant from the dummy data generator.</p><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Node.js installed</li><li>Access to the target Google Sheet (database sheet, not the reporting sheet)</li><li>VS Code or any editor that can open TSV files and select all text</li></ul><hr><h2 id="step-1-—-generate-the-tsv-files" tabindex="-1">Step 1 — Generate the TSV files <a class="header-anchor" href="#step-1-—-generate-the-tsv-files" aria-label="Permalink to &quot;Step 1 — Generate the TSV files&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate-dummy-data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate-v2.js</span></span></code></pre></div><p>This writes one TSV per database tab into <code>generate-dummy-data/</code>. Each run overwrites the previous output. The manifest (<code>MANIFEST.json</code>) logs row counts for verification.</p><hr><h2 id="step-2-—-import-each-tsv-into-its-sheet-tab" tabindex="-1">Step 2 — Import each TSV into its sheet tab <a class="header-anchor" href="#step-2-—-import-each-tsv-into-its-sheet-tab" aria-label="Permalink to &quot;Step 2 — Import each TSV into its sheet tab&quot;">​</a></h2><p>For each file in the table below, in order:</p><ol><li>Open the TSV in VS Code</li><li>Select All (<code>Ctrl+A</code> / <code>Cmd+A</code>)</li><li>Copy (<code>Ctrl+C</code> / <code>Cmd+C</code>)</li><li>In the Google Sheet, click the matching tab</li><li>Click cell <strong>A1</strong></li><li>Paste (<code>Ctrl+V</code> / <code>Cmd+V</code>)</li><li>If Google Sheets prompts &quot;Split text to columns&quot; — click <strong>No</strong> (the paste already handles tab-separated values correctly)</li></ol><h3 id="file-→-tab-mapping-import-in-this-order" tabindex="-1">File → Tab mapping (import in this order) <a class="header-anchor" href="#file-→-tab-mapping-import-in-this-order" aria-label="Permalink to &quot;File → Tab mapping (import in this order)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>TSV file</th><th>Sheet tab</th><th>Why this order</th></tr></thead><tbody><tr><td><code>disciplines.tsv</code></td><td><code>08. Disciplines</code></td><td>referenced by users</td></tr><tr><td><code>clients.tsv</code></td><td><code>04. Clients</code></td><td>referenced by projects</td></tr><tr><td><code>users.tsv</code></td><td><code>03. Users</code></td><td>referenced by projects, budgets, entries</td></tr><tr><td><code>tasks.tsv</code></td><td><code>05. Tasks</code></td><td>referenced by project_tasks, entries</td></tr><tr><td><code>projects.tsv</code></td><td><code>02. Projects</code></td><td>referenced by everything below</td></tr><tr><td><code>project_tasks.tsv</code></td><td><code>06. Project_Tasks</code></td><td>depends on projects + tasks</td></tr><tr><td><code>time_entries.tsv</code></td><td><code>01. Time Entries</code></td><td>depends on projects + users + tasks</td></tr><tr><td><code>budgets.tsv</code></td><td><code>07. Budgets</code></td><td>depends on projects + users</td></tr><tr><td><code>rate_history.tsv</code></td><td><code>13. Rate_History</code></td><td>depends on users</td></tr><tr><td><code>pending_pto.tsv</code></td><td><code>10. Pending_PTO</code></td><td>depends on users</td></tr><tr><td><code>unresolved_items.tsv</code></td><td><code>11. Unresolved_Items</code></td><td>depends on projects + users</td></tr></tbody></table><p>Tabs not in this list (<code>09. Conversations</code>, <code>12. Company_Calendar</code>, <code>14. Liabilities</code>) are not generated — leave them with their existing header row only, or clear them manually if resetting.</p><hr><h2 id="step-3-—-verify" tabindex="-1">Step 3 — Verify <a class="header-anchor" href="#step-3-—-verify" aria-label="Permalink to &quot;Step 3 — Verify&quot;">​</a></h2><p>After pasting, spot-check each tab:</p><ul><li>Row 1 is the <strong>header row</strong> (column names), not data</li><li>Row count roughly matches <code>MANIFEST.json</code></li><li>No blank rows between the header and first data row</li><li>The last row has data, not a trailing blank line</li></ul><p>Quick count: in Google Sheets, <code>=COUNTA(A:A)-1</code> in any empty cell gives the data row count (subtract 1 for the header).</p><hr><h2 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to &quot;Gotchas&quot;">​</a></h2><p><strong>Do not paste as &quot;values only&quot;.</strong> The default paste (<code>Ctrl+V</code>) is correct. &quot;Paste special → values only&quot; strips the tab delimiters and collapses everything into column A.</p><p><strong>Clear existing data first if rows have shifted.</strong> If the sheet already has data and you&#39;re replacing it, select all existing content below the header (rows 2 onward) and delete those rows before pasting. Otherwise old rows below the new data remain.</p><p><strong>Header row must stay.</strong> The bot reads sheets by positional column index — it does not look up column names. The header in row 1 is for human reference only, but it must remain in place so row 2 is the first data row.</p><p><strong>Google Sheets may auto-format dates.</strong> If date columns (e.g. <code>date</code> in Time Entries) display as numbers after paste, select the column and set the format to <code>Date</code> (<code>Format → Number → Date</code>).</p><p><strong>The reporting sheet is unaffected.</strong> This process only touches the database sheet. The reporting sheet pulls data via <code>IMPORTRANGE</code> and will reflect the new data automatically once the import is complete (allow a minute for IMPORTRANGE to refresh).</p><hr><h2 id="re-running" tabindex="-1">Re-running <a class="header-anchor" href="#re-running" aria-label="Permalink to &quot;Re-running&quot;">​</a></h2><p>The generator is fully idempotent — running it again produces a fresh consistent dataset. IDs are stable within a single run but will differ across runs (they are regenerated from 1 each time). Do not mix TSVs from different runs.</p>`,31)])])}const m=t(r,[["render",d]]);export{u as __pageData,m as default};
